// Prépare la chaîne signée "<timestamp>.<corps brut>" ; aucun module externe requis.
const MAX_AGE_SECONDS = 300;
const item = $input.first();
const headers = item.json.headers ?? {};
const timestamp = String(headers['x-lb-timestamp'] ?? '');
const received = String(headers['x-lb-signature'] ?? '');

let reason = null;
if (!item.binary?.data) reason = 'no_raw_body';
else if (!/^[0-9]{10}$/.test(timestamp)) reason = 'bad_timestamp';
else if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_AGE_SECONDS) reason = 'stale_timestamp';

let rawBody = '';
if (!reason) {
  const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
  rawBody = raw.toString('utf8');
}
return [{ json: { reason, received, rawBody, signedString: timestamp + '.' + rawBody } }];

// Compare la signature reçue à celle calculée (comparaison à temps constant) puis lit le JSON.
const prepared = $('Préparer la chaîne signée').first().json;
const reject = (reason) => [{ json: { valid: false, reason } }];
let secret = '';
try {
  secret = String($node['Calculer HMAC'].parameter.secret ?? '');
} catch {
  return reject('cannot_read_secret_param');
}

if (secret.startsWith('__')) return reject('secret_not_configured');
if (prepared.reason) return reject(prepared.reason);

const expected = 'sha256=' + String($input.first().json.computed ?? '');
const received = String(prepared.received);
let diff = expected.length ^ received.length;
const n = Math.max(expected.length, received.length);
for (let i = 0; i < n; i++) {
  diff |= (expected.charCodeAt(i) || 0) ^ (received.charCodeAt(i) || 0);
}
if (diff !== 0) return reject('bad_signature');

let payload;
try {
  payload = JSON.parse(prepared.rawBody);
} catch {
  return reject('bad_json');
}
return [{ json: { valid: true, payload } }];
